def choose_move(observation):
    # Defensive access to observation fields
    # Extract relevant data with defaults
    own_position = observation.get('agent', {}).get('position', (0, 0))
    grid_size = observation.get('grid_size', (1, 1))
    resource_positions = observation.get('resources', [])
    enemy_positions = observation.get('enemies', [])
    territory_owner = observation.get('territory', [])

    x, y = own_position

    # Compute move towards the closest resource, enemy, or expand territory
    def distance(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    target = None
    min_dist = float('inf')

    # Prioritize resource collection
    for res in resource_positions:
        dist = distance((x, y), res)
        if dist < min_dist:
            min_dist = dist
            target = res

    # Next, pursuit of enemies if no resources
    if target is None and enemy_positions:
        for enemy in enemy_positions:
            dist = distance((x, y), enemy)
            if dist < min_dist:
                min_dist = dist
                target = enemy

    # Else, expand territory or hold position
    if target is None:
        # Move towards unclaimed territory or stay put
        # For simplicity, move towards the closest unclaimed cell
        unclaimed = []
        for i in range(grid_size[0]):
            for j in range(grid_size[1]):
                owner = territory_owner.get((i, j))
                if owner != 'self':
                    unclaimed.append((i, j))
        if unclaimed:
            for cell in unclaimed:
                dist = distance((x, y), cell)
                if dist < min_dist:
                    min_dist = dist
                    target = cell
        if target is None:
            # No unclaimed territory, hold position
            return [0, 0]

    # Decide move direction
    dx = dy = 0
    if target:
        if target[0] > x:
            dx = 1
        elif target[0] < x:
            dx = -1
        if target[1] > y:
            dy = 1
        elif target[1] < y:
            dy = -1

    # Clamp move to one step
    if abs(dx) > 1:
        dx = int(dx/abs(dx))
    if abs(dy) > 1:
        dy = int(dy/abs(dy))

    return [dx, dy]
